package io.github.ningpp.compat;

import java.util.Arrays;

/**
 * Lightweight read-only array-slice container (generated by CSharpToJava converter).
 * Does not simulate C# ref-struct lifetime semantics.
 */
public final class ReadOnlySpan<T> {
    private final Object array;
    private String stringBacking;
    private int offset;
    private int length;

    public ReadOnlySpan(T[] array) {
        this.array = array;
        this.stringBacking = null;
        this.offset = 0;
        this.length = array.length;
    }

    /** Primitive byte[] backing — mirrors C# byte[] → ReadOnlySpan&lt;byte&gt;. */
    public ReadOnlySpan(byte[] array) {
        this.array = array;
        this.stringBacking = null;
        this.offset = 0;
        this.length = array.length;
    }

    /** Copy constructor — allows wrapping an existing ReadOnlySpan without type inference issues */
    public ReadOnlySpan(ReadOnlySpan<T> other) {
        this.array = other.array;
        this.stringBacking = other.stringBacking;
        this.offset = other.offset;
        this.length = other.length;
    }

    public ReadOnlySpan(T[] array, int offset, int length) {
        if (offset < 0 || length < 0 || offset + length > array.length) {
            throw new IndexOutOfBoundsException(
                "offset=" + offset + ", length=" + length + ", arrayLength=" + array.length);
        }
        this.array = array;
        this.stringBacking = null;
        this.offset = offset;
        this.length = length;
    }

    /** Primitive byte[] slice backing — mirrors C# byte[] → ReadOnlySpan&lt;byte&gt;. */
    public ReadOnlySpan(byte[] array, int offset, int length) {
        if (offset < 0 || length < 0 || offset + length > array.length) {
            throw new IndexOutOfBoundsException(
                "offset=" + offset + ", length=" + length + ", arrayLength=" + array.length);
        }
        this.array = array;
        this.stringBacking = null;
        this.offset = offset;
        this.length = length;
    }

    public ReadOnlySpan(Span<T> span) {
        this.array = span.getArray();
        this.stringBacking = null;
        this.offset = span.getOffset();
        this.length = span.length();
    }

    /**
     * Creates a lazy, String-backed span. No char array is copied: each get(i)
     * reads directly from the String (and boxes the single char), mirroring C#
     * string.AsSpan() which views the string in place. Without this, every
     * asSpan call materialized the whole substring as a boxed Character[] —
     * e.g. RegexInterpreter.findFirstChar called asSpan on the remaining input
     * on every match attempt, allocating ~1 MB of boxed chars per call.
     */
    public static ReadOnlySpan<Character> fromString(String s, int start, int length) {
        if (start < 0 || length < 0 || start + length > s.length()) {
            throw new IndexOutOfBoundsException(
                "start=" + start + ", length=" + length + ", stringLength=" + s.length());
        }
        ReadOnlySpan<Character> span = new ReadOnlySpan<>(new Character[0]);
        span.stringBacking = s;
        span.offset = start;
        span.length = length;
        return span;
    }

    public int length() {
        return length;
    }

    /** Alias for length() — matches C# Span.Length property getter translation */
    public int getLength() {
        return length;
    }

    public T get(int index) {
        if (index < 0 || index >= length) {
            throw new IndexOutOfBoundsException("index=" + index + ", length=" + length);
        }
        if (stringBacking != null) {
            @SuppressWarnings("unchecked")
            T value = (T) java.lang.Character.valueOf(stringBacking.charAt(offset + index));
            return value;
        }
        if (array instanceof byte[] bytes) {
            @SuppressWarnings("unchecked")
            T value = (T) java.lang.Integer.valueOf(bytes[offset + index] & 0xFF);
            return value;
        }
        @SuppressWarnings("unchecked")
        T value = ((T[]) array)[offset + index];
        return value;
    }

    public ReadOnlySpan<T> slice(int start) {
        return slice(start, length - start);
    }

    public ReadOnlySpan<T> slice(int start, int len) {
        if (start < 0 || len < 0 || start + len > length) {
            throw new IndexOutOfBoundsException(
                "start=" + start + ", len=" + len + ", length=" + length);
        }
        if (stringBacking != null) {
            return (ReadOnlySpan<T>) (ReadOnlySpan<?>) fromString(stringBacking, offset + start, len);
        }
        if (array instanceof byte[] bytes) {
            return new ReadOnlySpan<>((T[]) toIntegerArray(bytes, offset + start, len));
        }
        return new ReadOnlySpan<>((T[]) array, offset + start, len);
    }

    public T[] toArray() {
        if (array instanceof byte[] bytes) {
            return (T[]) toIntegerArray(bytes, offset, length);
        }
        return Arrays.copyOfRange((T[]) array, offset, offset + length);
    }

    /**
     * Materializes the slice as a primitive byte[] (elements narrowed from the
     * boxed representation). Used to pin a byte span for MemorySegment.ofArray.
     */
    public byte[] toByteArray() {
        if (array instanceof byte[] bytes) {
            return Arrays.copyOfRange(bytes, offset, offset + length);
        }
        byte[] result = new byte[length];
        for (int i = 0; i < length; i++) {
            result[i] = (byte)(((Number) get(i)).intValue() & 0xFF);
        }
        return result;
    }

    /**
     * Rebuilds a ReadOnlySpan&lt;Integer&gt; (the converter's byte-span shape) from a
     * pinned MemorySegment, mirroring C# new ReadOnlySpan&lt;byte&gt;((byte*)ptr, length).
     */
    public static ReadOnlySpan<Integer> fromByteSegment(java.lang.foreign.MemorySegment segment, int length) {
        Integer[] data = new Integer[length];
        for (int i = 0; i < length; i++) {
            data[i] = segment.get(java.lang.foreign.ValueLayout.JAVA_BYTE, i) & 0xFF;
        }
        return new ReadOnlySpan<>(data);
    }

    public void copyTo(Span<T> destination) {
        int copyLength = Math.min(length, destination.length());
        for (int i = 0; i < copyLength; i++) {
            destination.set(i, get(i));
        }
    }

    @Override
    public String toString() {
        if (stringBacking != null) {
            return stringBacking.substring(offset, offset + length);
        }
        if (array instanceof Character[] chars) {
            StringBuilder sb = new StringBuilder(length);
            for (int i = 0; i < length; i++) {
                sb.append(chars[offset + i]);
            }
            return sb.toString();
        }
        return super.toString();
    }

    private static Integer[] toIntegerArray(byte[] bytes, int offset, int length) {
        Integer[] copy = new Integer[length];
        for (int i = 0; i < length; i++) {
            copy[i] = bytes[offset + i] & 0xFF;
        }
        return copy;
    }
}
